// Trata o evento recebido do Mercado Pago (Webhooks v1 e v2 / IPN)
const body = $json.body || {};
const query = $json.query || {};

const paymentId = (body.data && body.data.id) || body.id || query.id || query["data.id"] || null;
const topic = body.type || body.topic || query.topic || "payment";

return [{
  json: {
    paymentId,
    topic,
    isPayment: topic === "payment"
  }
}];

const payment = $json;
const payer = payment.payer || {};
const additionalInfo = payment.additional_info || {};
const payerInfo = additionalInfo.payer || {};

const nome = (payer.first_name ? payer.first_name + " " + (payer.last_name || "") : payerInfo.first_name) || "Lojista VIP";
const rawPhone = (payer.phone && payer.phone.number) || (payerInfo.phone && payerInfo.phone.number) || "5511999999999";
const cleanPhone = String(rawPhone).replace(/\D/g, "");
const whatsapp = cleanPhone.startsWith("55") ? cleanPhone : "55" + cleanPhone;
const valor = Number(payment.transaction_amount || 97.00);

const slugLoja = String(nome).toLowerCase().replace(/[^a-z0-9]/g, "-");
const webhookUrlCliente = "https://drophub-n8n.dvzzxm.easypanel.host/webhook/auditor-checkout?loja=" + slugLoja + "&wa=" + whatsapp;

const mensagemBoasVindas = "*BEM-VINDO AO AUDITOR SILENCIOSO!*\n\n" +
  "Olá *" + nome.trim() + "*! Seu pagamento de *R$ " + valor.toFixed(2) + "* foi confirmado via Mercado Pago.\n\n" +
  "🛡️ Seu sentinela de checkout 24/7 já está ativo por apenas *R$ 3,23 por dia*!\n\n" +
  "👉 *Como ativar na sua loja (Nuvemshop, Shopify, Yampi, Appmax):*\n" +
  "1. No painel da sua loja, vá em Configurações > Webhooks.\n" +
  "2. Adicione esta URL para eventos de pedidos:\n" +
  webhookUrlCliente + "\n\n" +
  "A partir de agora, se houver qualquer pico de recusa de cartões ou checkout travado, eu te aviso aqui no mesmo segundo! 🚀";

return [{ json: { nome, whatsapp, valor, webhookUrlCliente, mensagemBoasVindas } }];

const query = $json.query || {};
const body = $json.body || {};

const lojaId = query.loja || body.store_id || "loja-padrao";
const whatsappDestino = query.wa || "5511999999999";

let status = String(body.status || body.event || "").toLowerCase();
let isRecusa = status.includes("refused") || status.includes("recusad") || status.includes("failed") || status.includes("denied");
let isAprovado = status.includes("paid") || status.includes("pago") || status.includes("approved") || status.includes("sucesso");
let formaPagamento = body.payment_method || (body.payment && body.payment.method) || "Cartão";
let valorVenda = Number(body.total || body.amount || (body.order && body.order.total) || 0);

const staticData = $getWorkflowStaticData("global");
staticData.historicoLojas = staticData.historicoLojas || {};
staticData.historicoLojas[lojaId] = staticData.historicoLojas[lojaId] || { pedidos: [], ultimoAlerta: 0, ultimaVendaTimestamp: Date.now() };

const dadosLoja = staticData.historicoLojas[lojaId];
const agora = Date.now();
if (isAprovado) dadosLoja.ultimaVendaTimestamp = agora;

dadosLoja.pedidos.unshift({ timestamp: agora, status: isRecusa ? "recusado" : (isAprovado ? "aprovado" : "outro"), formaPagamento, valor: valorVenda });
dadosLoja.pedidos = dadosLoja.pedidos.filter(p => agora - p.timestamp <= 2 * 60 * 60 * 1000).slice(0, 20);

const pedidosCartao = dadosLoja.pedidos.filter(p => String(p.formaPagamento).toLowerCase().includes("cart") || String(p.formaPagamento).toLowerCase().includes("credit"));
const recusasCartao = pedidosCartao.filter(p => p.status === "recusado").length;
const taxaRecusa = pedidosCartao.length >= 4 ? (recusasCartao / pedidosCartao.length) * 100 : 0;

let temAlerta = false;
let tipoAlerta = "";
let mensagemAlerta = "";

const tempoDesdeUltimoAlerta = agora - dadosLoja.ultimoAlerta;
if (taxaRecusa >= 25 && recusasCartao >= 3 && tempoDesdeUltimoAlerta > 25 * 60 * 1000) {
  temAlerta = true;
  tipoAlerta = "PICO_RECUSA";
  dadosLoja.ultimoAlerta = agora;
  mensagemAlerta = "🚨 *[AUDITOR SILENCIOSO] PICO DE RECUSA DETECTADO!*\n\n" +
    "Atenção! Sua loja *" + lojaId + "* teve *" + recusasCartao + " cartões recusados* nos últimos minutos.\n\n" +
    "📊 *Taxa de Recusa:* " + taxaRecusa.toFixed(1) + "% (limite de segurança: 15%)\n" +
    "💳 *Forma de Pagamento:* Cartão de Crédito\n\n" +
    "💡 *Ação Rápida:* Verifique a conexão do seu gateway ou antifraude agora para não queimar verba de anúncios!";
}

return [{ json: { lojaId, whatsappDestino, isRecusa, isAprovado, taxaRecusa, temAlerta, tipoAlerta, mensagemAlerta } }];

const staticData = $getWorkflowStaticData("global");
const lojas = staticData.historicoLojas || {};
const resultados = [];

for (const [lojaId, dados] of Object.entries(lojas)) {
  const pedidosHoje = dados.pedidos || [];
  const aprovados = pedidosHoje.filter(p => p.status === "aprovado");
  const recusados = pedidosHoje.filter(p => p.status === "recusado");
  const totalFaturado = aprovados.reduce((acc, cur) => acc + (cur.valor || 0), 0);
  const taxaAprovacao = pedidosHoje.length > 0 ? ((aprovados.length / pedidosHoje.length) * 100).toFixed(1) : 100;

  const msgFechamento = "🌙 *[AUDITOR SILENCIOSO] FECHAMENTO DO DIA*\n\n" +
    "Resumo da loja *" + lojaId + "*:\n\n" +
    "💰 *Faturamento Registrado:* R$ " + totalFaturado.toFixed(2) + "\n" +
    "📈 *Taxa de Aprovação:* " + taxaAprovacao + "%\n" +
    "🛒 *Pedidos no Período:* " + pedidosHoje.length + " (" + aprovados.length + " pagos / " + recusados.length + " recusados)\n\n" +
    "Seu sentinela continuará em alerta durante a madrugada! Tenha uma excelente noite.";

  resultados.push({ json: { lojaId, totalFaturado, taxaAprovacao, mensagem: msgFechamento } });
}

return resultados.length > 0 ? resultados : [{ json: { mensagem: "Sem lojas ativas no momento" } }];

const body = $json.body || {};
const lead = body.lead || {};
const sim = body.simulation || {};

const name = lead.name || "Lojista";
const rawPhone = String(lead.whatsapp || "5511999999999").replace(/\D/g, "");
const fullPhone = rawPhone.startsWith("55") ? rawPhone : "55" + rawPhone;

const price = Number(sim.price || 0).toFixed(2);
const profit = Number(sim.netProfit || 0).toFixed(2);
const margin = Number(sim.netMargin || 0).toFixed(1);
const gateway = sim.gatewayName || "Mercado Pago";
const platform = sim.platformName || "E-commerce";

const reportMsg = "*[DROPHUB TOOLS] SEU RELATÓRIO DE LUCRO REAL*\n\n" +
  "Olá *" + name + "*! Aqui está o resumo da sua simulação na Calculadora:\n\n" +
  "🏷️ *Preço de Venda:* R$ " + price + "\n" +
  "💳 *Gateway:* " + gateway + " | *Plataforma:* " + platform + "\n" +
  "💰 *LUCRO LÍQUIDO REAL:* R$ " + profit + " (" + margin + "% de margem)\n\n" +
  "💡 *Diagnóstico de Otimização:*\n" +
  "Você sabia que checkouts travados e recusas de cartão comem até 30% do faturamento da sua loja em silêncio?\n\n" +
  "🛡️ *Conheça o Auditor Silencioso por apenas R$ 3,23 por dia (R$ 97/mês):*\n" +
  "https://calculadoradoecommerce.com.br/auditor.html";

return [{ json: { fullPhone, reportMsg } }];
